 }
 var fd = new FormData();
 Object.keys(data).forEach(function (k) { fd.append(k, data[k]); });
 fetch(ep, { method: "POST", body: fd, headers: { "Accept": "application/json" } })
 .then(function (r) { if (r.ok) onOk(); else onErr(); })
 .catch(onErr);
 }

